(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const cards = [...document.querySelectorAll('.tb-project-main')];
  (cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0]).click();
  await sleep(3000);
  const out = { title: document.querySelector('.pj-title')?.textContent || null };

  // 钩住 createObjectURL，把导出的 .ecp 字节留下来检查（真实导出路径，只是不落盘）
  let captured = null;
  const orig = URL.createObjectURL.bind(URL);
  URL.createObjectURL = (blob) => { captured = blob; return orig(blob); };
  [...document.querySelectorAll('.pj-head-actions > button')].find((b) => b.textContent.includes('保存作品文件')).click();
  await sleep(3000);
  URL.createObjectURL = orig;

  if (!captured) { out.exported = false; return JSON.stringify(out); }
  const buf = new Uint8Array(await captured.arrayBuffer());
  const text = new TextDecoder('latin1').decode(buf);
  out.exported = true;
  out.size = captured.size;
  out.type = captured.type;
  out.zipHead = Array.from(buf.slice(0, 4)).map((b) => b.toString(16).padStart(2, '0')).join(' ');
  out.entries = [...new Set([...text.matchAll(/(?:manifest|components|sections|images|thumbnail)[A-Za-z0-9_./-]*\.(?:json|jpg|png|txt)/g)].map((m) => m[0]))];
  out.hasReadme = text.includes('README.txt');
  // 分享不能带上本机凭据
  out.leaksKey = /sk-[A-Za-z0-9]|apiKey|api_key|ai_config|teacherCode/.test(text);
  out.notice = document.querySelector('.tb-ok')?.textContent || null;
  return JSON.stringify(out);
})()
